import React, { useEffect, useRef } from "react";

/**
 * ParticleBackground:
 * Renders an ultra-lightweight, 60fps ambient particle canvas
 * with warm rose, gold, and champagne floating dust embers.
 */
export const ParticleBackground = () => {
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    let animationFrameId;
    let width = (canvas.width = window.innerWidth);
    let height = (canvas.height = window.innerHeight);

    // Check prefers-reduced-motion
    const prefersReducedMotion = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;

    // Responsive particle count (fewer on mobile for battery & performance)
    const particleCount = window.innerWidth < 768 ? 24 : 45;
    const particles = [];

    const colors = [
      "rgba(226, 164, 153, ", // Soft rose
      "rgba(246, 213, 205, ", // Blush
      "rgba(232, 216, 200, ", // Champagne gold
      "rgba(255, 255, 255, ", // Star white
    ];

    for (let i = 0; i < particleCount; i++) {
      particles.push({
        x: Math.random() * width,
        y: Math.random() * height,
        radius: Math.random() * 1.8 + 0.6,
        colorBase: colors[Math.floor(Math.random() * colors.length)],
        alpha: Math.random() * 0.4 + 0.1,
        targetAlpha: Math.random() * 0.4 + 0.1,
        vx: (Math.random() - 0.5) * 0.25,
        vy: -Math.random() * 0.35 - 0.1, // Gently floats upward
        pulseSpeed: 0.008 + Math.random() * 0.012,
      });
    }

    const handleResize = () => {
      width = canvas.width = window.innerWidth;
      height = canvas.height = window.innerHeight;
    };

    window.addEventListener("resize", handleResize);

    const render = () => {
      ctx.clearRect(0, 0, width, height);

      // Render floating embers
      for (let i = 0; i < particles.length; i++) {
        const p = particles[i];

        if (!prefersReducedMotion) {
          p.x += p.vx;
          p.y += p.vy;

          // Pulse opacity smoothly
          p.alpha += (p.targetAlpha - p.alpha) * p.pulseSpeed;
          if (Math.abs(p.targetAlpha - p.alpha) < 0.02) {
            p.targetAlpha = Math.random() * 0.45 + 0.1;
          }

          // Wrap boundaries gently
          if (p.y < -10) {
            p.y = height + 10;
            p.x = Math.random() * width;
          }
          if (p.x < -10) p.x = width + 10;
          if (p.x > width + 10) p.x = -10;
        }

        ctx.beginPath();
        ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
        ctx.fillStyle = `${p.colorBase}${p.alpha})`;
        ctx.shadowBlur = 8;
        ctx.shadowColor = "rgba(226, 164, 153, 0.4)";
        ctx.fill();
      }

      animationFrameId = requestAnimationFrame(render);
    };

    render();

    return () => {
      window.removeEventListener("resize", handleResize);
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  return (
    <div className="particle-container" aria-hidden="true">
      <div className="ambient-glow ambient-glow-top" />
      <div className="ambient-glow ambient-glow-bottom" />
      <canvas ref={canvasRef} className="particle-canvas" />
    </div>
  );
};

export default ParticleBackground;
